      created_at: product.created_at,

      archived: product.is_archived
    }
  });

}

return rows;

const rows = [];

const products = $input.first().json.items;

for (const product of products) {

  const fbo = product.stocks.find(s => s.type === 'fbo');
  const fbs = product.stocks.find(s => s.type === 'fbs');

  rows.push({
    json: {
      offer_id: product.offer_id,

      stock_fbo: fbo ? fbo.present : 0,
      stock_fbs: fbs ? fbs.present : 0,
      reserved_fbs: fbs ? fbs.reserved : 0,

      updated_stock_at: new Date().toISOString()
    }
  });

}

return rows;

const rows = [];

const input = $input.first().json.result.operations;

for (const op of input) {

    const item = op.items?.[0] ?? {};

    // Сумма всех услуг
    const services = op.services ?? [];

    const serviceName = services
        .map(s => s.name)
        .join('; ');

    const serviceAmount = services
        .reduce((sum, s) => sum + Number(s.price ?? 0), 0);

    rows.push({
        json: {

            operation_id: op.operation_id,

            posting_number: op.posting?.posting_number ?? null,

            order_number: op.posting?.order_number ?? null,

            operation_type: op.operation_type,

            operation_type_name: op.operation_type_name,

            operation_date: op.operation_date,

            amount: op.amount,

            delivery_charge: op.delivery_charge ?? 0,

            return_delivery_charge: op.return_delivery_charge ?? 0,

            accruals_for_sale: op.accruals_for_sale ?? 0,

            sale_commission: op.sale_commission ?? 0,

            service_name: serviceName,

            service_amount: serviceAmount,

            sku: item.sku ?? null

        }
    });

}

return rows;

